create or replace package body t003_fees as
  c_rate    constant number := 0.01;
  c_min_fee constant number := 1;
  c_max_fee constant number := 10;

  function fee_for(p_amount in number) return number is
  begin
    -- Calculate the percentage fee first
    DECLARE
      l_calculated_fee NUMBER := round(p_amount * c_rate, 2);
    BEGIN
      -- Apply minimum and maximum constraints correctly
      RETURN greatest(c_min_fee, least(l_calculated_fee, c_max_fee));
    END;
  end fee_for;
end t003_fees;
/
